import React, { useMemo } from "react";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  ResponsiveContainer
} from "recharts";

function InsightsPage({ transactions, alerts, insights, darkMode, goBack }) {
    // ✅ Build chart data from transactions
const categoryTotals = {};

transactions.forEach((t) => {
  const cat = (t.category || "other").toLowerCase();
  const amount = Number(t.amount || 0);

  categoryTotals[cat] = (categoryTotals[cat] || 0) + amount;
});

// convert to recharts format
const data = Object.keys(categoryTotals).map((key) => ({
  name: key,
  value: categoryTotals[key]
}));

  const COLORS = ["#4f6df5", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6"];

  // 📊 Category Data
  const categoryData = useMemo(() => {
    let totals = {};
    transactions.forEach(t => {
      const cat = t.category || "Other";
      totals[cat] = (totals[cat] || 0) + Number(t.amount || 0);
    });

    return Object.entries(totals).map(([name, value]) => ({
      name,
      value
    }));
  }, [transactions]);

  // 💰 Total Spend
  const totalSpend = useMemo(() => {
    return transactions.reduce((sum, t) => sum + Number(t.amount || 0), 0);
  }, [transactions]);

  // 🔝 Top Category
  const topCategory = useMemo(() => {
    if (!categoryData.length) return null;
    return [...categoryData].sort((a, b) => b.value - a.value)[0];
  }, [categoryData]);

  // 🧠 AI Summary
  const aiSummary = useMemo(() => {
    if (!transactions.length) return "Upload a statement to see insights.";

    const alertMsg = alerts.find(a => a.exceeded)
      ? "Some of your budgets have been exceeded."
      : "You are mostly within your budget limits.";

    return `You spent a total of ₹${totalSpend.toFixed(0)} during this period. 
Your highest spending category was ${topCategory?.name}, indicating a key expense driver. 
${alertMsg} Your spending behavior suggests ${
      insights.length > 3 ? "diverse financial activity" : "disciplined spending"
    }.`;
  }, [transactions, alerts, insights, totalSpend, topCategory]);

  return (
    <div className="container" style={{ marginTop: "20px" }}>

      {/* HEADER */}
      <div className="card" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2>AI Financial Insights</h2>
          <p style={{ fontSize: "13px", color: "#6b7280" }}>
            Smart analysis of your spending behavior
          </p>
        </div>

        <button
          onClick={goBack}
          style={{
            padding: "6px 14px",
            borderRadius: "8px",
            border: "none",
            background: "#4f6df5",
            color: "#fff",
            cursor: "pointer"
          }}
        >
          ← Back
        </button>
      </div>

      {/* KPI CARDS */}
      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(200px,1fr))",
        gap: "16px",
        marginTop: "20px"
      }}>
        <div className="card">
          <h4>Total Spend</h4>
          <p style={{ fontSize: "20px", fontWeight: "600" }}>₹{totalSpend.toFixed(0)}</p>
        </div>

        <div className="card">
          <h4>Top Category</h4>
          <p style={{ fontSize: "18px", fontWeight: "600" }}>
            {topCategory?.name || "-"}
          </p>
        </div>

        <div className="card">
          <h4>Transactions</h4>
          <p style={{ fontSize: "18px", fontWeight: "600" }}>
            {transactions.length}
          </p>
        </div>
      </div>

      {/* AI SUMMARY */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>AI Summary</h3>
        <p style={{ lineHeight: "1.7", fontSize: "14px" }}>{aiSummary}</p>
      </div>

      {/* CHARTS GRID */}
      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(300px,1fr))",
        gap: "20px",
        marginTop: "20px"
      }}>

        {/* PIE */}
        <div
  style={{
    background: darkMode ? "#111827" : "#ffffff",
    padding: "24px",
    borderRadius: "16px",
    boxShadow: darkMode
      ? "0 4px 20px rgba(0,0,0,0.4)"
      : "0 4px 20px rgba(0,0,0,0.08)"
  }}
>
  <h3 style={{ marginBottom: "16px" }}>Spending Breakdown</h3>

  <ResponsiveContainer width="100%" height={320}>
    <PieChart>
      
      {/* ✅ Gradient definitions */}
      <defs>
        <linearGradient id="grad1" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#4f6df5" />
          <stop offset="100%" stopColor="#6a85ff" />
        </linearGradient>

        <linearGradient id="grad2" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#22c55e" />
          <stop offset="100%" stopColor="#16a34a" />
        </linearGradient>

        <linearGradient id="grad3" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#f59e0b" />
          <stop offset="100%" stopColor="#d97706" />
        </linearGradient>

        <linearGradient id="grad4" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#ef4444" />
          <stop offset="100%" stopColor="#dc2626" />
        </linearGradient>
      </defs>

      <Pie
        data={data}
        dataKey="value"
        nameKey="name"
        cx="50%"
        cy="50%"
        innerRadius={70}   // donut style
        outerRadius={110}
        paddingAngle={3}
        cornerRadius={10}  // 🔥 rounded slices
      >
        {data.map((entry, index) => {
          const fills = [
            "url(#grad1)",
            "url(#grad2)",
            "url(#grad3)",
            "url(#grad4)"
          ];
          return <Cell key={index} fill={fills[index % fills.length]} />;
        })}
      </Pie>

      {/* ✅ CENTER LABEL */}
      <text
        x="50%"
        y="50%"
        textAnchor="middle"
        dominantBaseline="middle"
        style={{
          fontSize: "16px",
          fontWeight: "600",
          fill: darkMode ? "#e5e7eb" : "#111827"
        }}
      >
        ₹{data.reduce((sum, d) => sum + d.value, 0)}
      </text>

      {/* ✅ TOOLTIP */}
      <Tooltip
        contentStyle={{
          borderRadius: "10px",
          border: "none",
          background: darkMode ? "#1f2937" : "#fff",
          boxShadow: "0 4px 12px rgba(0,0,0,0.15)"
        }}
      />

      {/* ✅ LEGEND */}
      <Legend
        verticalAlign="bottom"
        height={36}
        iconType="circle"
      />

    </PieChart>
  </ResponsiveContainer>
</div>

        {/* BAR */}
        <div className="card">
          <h3>Category Comparison</h3>
          <div style={{ width: "100%", height: 260 }}>
            <ResponsiveContainer>
              <BarChart data={categoryData}>
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="value" radius={[6, 6, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* INSIGHTS LIST */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Detailed Insights</h3>

        {insights.length > 0 ? (
          insights.map((i, idx) => (
            <div
              key={idx}
              style={{
                padding: "10px",
                borderRadius: "8px",
                marginBottom: "8px",
                background: darkMode ? "#1f2937" : "#f9fafb"
              }}
            >
              {i}
            </div>
          ))
        ) : (
          <p>No insights available</p>
        )}
      </div>

    </div>
  );
}

export default InsightsPage;
